{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const targets = issues.filter(i => i.status === "unresolved" && i.count >= 0);

  // duplicate guard: look for an existing Linear issue for each target
  const toCreate: typeof targets = [];
  const skipped: { shortId: string; existing: string }[] = [];
  for (const i of targets) {
    const { issues: found } = await sdk.linear.searchIssues({ query: `[Sentry] ${i.shortId}` });
    const match = found.find(f => f.title === `[Sentry] ${i.shortId}`);
    if (match) skipped.push({ shortId: i.shortId, existing: match.identifier });
    else toCreate.push(i);
  }

  const created = [];
  for (const i of toCreate) {
    const res = await sdk.linear.createIssue({
      title: `[Sentry] ${i.shortId}`,
      description: i.culprit,
    });
    created.push({ shortId: i.shortId, description: i.culprit, issue: res });
  }

  return {
    planned: toCreate.map(i => ({ title: `[Sentry] ${i.shortId}`, description: i.culprit })),
    createdCount: toCreate.length,
    created,
    skipped,
    excluded: issues.filter(i => !(i.status === "unresolved" && i.count >= 0)).map(i => ({ shortId: i.shortId, status: i.status, count: i.count })),
  };
}"}

